/* M109 – Accès et protection des données (logiprof, leçons 9.1 à 9.5).
   Objectifs : A2.2, A2.3, B1.5, B1.6, D5.3 (leçon « M109 – Objectifs »).
   a[0] = bonne réponse (mélangée à l'affichage). « Hors support » = complément vérifié hors du cours. */
const HS_LPD = "Hors support · nLPD (en vigueur depuis le 1.9.2023)";
const HS_NCSC = "Hors support · bonnes pratiques NCSC";
const HS_POSTE = "Hors support · Poste CH, « Procuration à la Poste »";
window.OBJ = [
/* ============ 1 · A2.2 AUTORISATIONS D'ACCÈS ============ */
{code:"A2.2", t:"Autorisations d’accès", g:"J’explique le principe des autorisations d’accès aux bâtiments et aux installations ainsi que les droits d’accès aux applications et je décris les systèmes utilisés dans mon entreprise pour faire respecter ces autorisations et ces droits. (C2)", col:"teal", ic:"badge",
ch:[
{k:"qcm",q:"Selon quel critère les clés ou badges sont-ils distribués dans une entreprise ?",a:["En fonction des responsabilités de chacun","Selon l’ancienneté dans l’entreprise","De manière identique à tous les employés","Selon le choix personnel de chaque employé"],ex:"Chaque employé reçoit un accès spécifique aux locaux : les clés ou badges sont distribués selon les responsabilités.",ref:"Leçon 9.1"},
{k:"tf",q:"Vous pouvez prêter votre badge à un collègue de confiance sans demander d’autorisation.",v:false,ex:"Règle n° 1 : ne jamais confier sa clé ou son badge à quelqu’un d’autre sans autorisation.",ref:"Leçon 9.1"},
{k:"multi",q:"Quelles règles d’utilisation des clés et badges figurent dans le cours ?",good:["Ne jamais confier sa clé sans autorisation","Conserver sa clé en sécurité quand elle ne sert pas","Ne jamais laisser la clé sur la porte","Ne pas identifier l’entreprise sur la clé"],bad:["Cacher un double sous le paillasson","Inscrire l’adresse du dépôt sur le porte-clés"],ex:"Le cours cite cinq règles : ne pas confier, conserver en sécurité, ne pas laisser sur la porte, pas d’endroit évident (paillasson), pas d’identification de l’entreprise.",ref:"Leçon 9.1"},
{k:"tf",q:"Il est conseillé d’inscrire le nom de l’entreprise sur la clé pour qu’on puisse la rapporter en cas de perte.",v:false,ex:"Pour des raisons de sécurité, l’entreprise ne doit pas être identifiable sur la clé : celui qui la trouve saurait où elle sert.",ref:"Leçon 9.1"},
{k:"qcm",q:"Que devez-vous faire si vous perdez une clé de l’entreprise ?",a:["Le signaler immédiatement à l’employeur","Attendre quelques jours qu’elle réapparaisse","Faire faire une copie à vos frais sans rien dire","Emprunter la clé d’un collègue en attendant"],ex:"Une perte doit être signalée immédiatement à l’employeur pour qu’il prenne des mesures préventives.",ref:"Leçon 9.1"},
{k:"qcm",q:"Pourquoi la perte d’une clé mécanique peut-elle coûter cher ?",a:["Il faut parfois remplacer toutes les serrures qu’elle ouvre","La clé elle-même est fabriquée dans un métal précieux","L’assurance refuse toujours de couvrir l’employé","L’entreprise doit fermer jusqu’à ce qu’on la retrouve"],ex:"Perdre une clé peut nécessiter le remplacement de toutes les serrures accessibles avec cette clé.",ref:"Leçon 9.1"},
{k:"fill",q:"Une clé électronique perdue peut être ___, ce qui évite de remplacer les serrures.",a:["désactivée","dupliquée","gravée","prêtée"],ex:"Dans les systèmes modernes, la clé électronique est désactivée : pas de changement de serrures, mais d’autres coûts.",ref:"Leçon 9.1"},
{k:"tf",q:"Désactiver un badge électronique perdu n’engendre aucun coût pour l’entreprise.",v:false,ex:"La désactivation évite de remplacer les serrures mais engendre d’autres coûts (nouveau badge, gestion du système).",ref:"Leçon 9.1"},
{k:"qcm",q:"Comment commence généralement l’accès au système informatique de l’entreprise ?",a:["Par un nom d’utilisateur et un mot de passe","Par la présentation de son badge au chef","Par une signature sur un registre papier","Par l’adresse e-mail de l’entreprise seule"],ex:"L’accès au système informatique commence généralement par un nom d’utilisateur et un mot de passe.",ref:"Leçon 9.5"},
{k:"qcm",q:"Pourquoi le système informatique enregistre-t-il chaque accès ?",a:["Pour détecter toute intrusion non autorisée","Pour calculer le salaire de chaque employé","Pour accélérer la connexion des utilisateurs","Pour publier l’activité de chaque employé"],ex:"Le système enregistre chaque accès afin de détecter toute intrusion non autorisée.",ref:"Leçon 9.5"},
{k:"fill",q:"Les droits d’accès aux applications sont attribués en fonction des ___ des employés.",a:["responsabilités","préférences","âges","horaires"],ex:"Comme pour les clés, les droits d’accès informatiques suivent les responsabilités de chacun.",ref:"Leçon 9.5"},
{k:"qcm",q:"Qui gère généralement les réseaux et les systèmes informatiques de l’entreprise ?",a:["Les administrateurs système","Les logisticiens du quai","Les clients de l’entreprise","Les fournisseurs de matériel"],ex:"Les administrateurs système gèrent les réseaux ; tous les collaborateurs doivent cependant respecter les règles.",ref:"Leçon 9.5"},
{k:"tf",q:"Comme les administrateurs système gèrent l’informatique, les logisticiens n’ont aucune règle à respecter.",v:false,ex:"Tous les collaborateurs, y compris les logisticiens, doivent respecter les règles établies.",ref:"Leçon 9.5"},
{k:"match",q:"Associez chaque moyen à ce qu’il contrôle.",p:[["Clé ou badge","L’accès aux locaux et installations"],["Identifiant et mot de passe","L’accès au système informatique"],["Droits d’accès","Les applications utilisables selon la fonction"],["Journal des accès","La détection des intrusions"]],ex:"Accès physique (clés, badges) et accès informatique (identifiant, droits, journal) suivent la même logique.",ref:"Leçons 9.1 et 9.5"},
{k:"sort",q:"Accès aux locaux ou accès aux applications ? Classez.",c:["Accès aux locaux","Accès aux applications"],it:[["Badge électronique",0],["Clé de la porte du dépôt",0],["Mot de passe",1],["Droits attribués par l’administrateur",1],["Serrure du local de stockage",0],["Nom d’utilisateur",1]],ex:"Clés, badges et serrures protègent les bâtiments ; identifiants, mots de passe et droits protègent les applications.",ref:"Leçons 9.1 et 9.5"},
{k:"order",q:"Vous perdez votre badge électronique. Remettez les étapes dans l’ordre.",a:["Constater la perte du badge","Signaler la perte à l’employeur","Désactivation du badge perdu","Remise d’un nouveau badge"],ex:"Signaler immédiatement permet à l’employeur de désactiver le badge avant qu’il soit utilisé par un tiers.",ref:"Leçon 9.1"},
{k:"odd",q:"Trouvez l’intrus : ces comportements respectent les règles des clés, sauf un.",a:["Laisser la clé sur la porte du local","Ranger sa clé en lieu sûr","Signaler aussitôt une clé perdue","Refuser de prêter sa clé sans autorisation"],ex:"Une clé ne doit jamais rester sur la porte.",ref:"Leçon 9.1"},
{k:"case",s:"Un livreur externe vous demande votre badge pour aller chercher un transpalette dans l’entrepôt pendant que vous déchargez son camion.",q:"Que faites-vous ?",a:["Vous refusez et l’accompagnez ou appelez un responsable","Vous lui prêtez le badge s’il le rend rapidement","Vous lui donnez plutôt le code de la porte","Vous laissez la porte ouverte pour gagner du temps"],ex:"Le badge ne se confie jamais sans autorisation : l’accès de la personne externe doit être contrôlé.",ref:"Leçon 9.1"},
{k:"case",s:"En fin de journée, un collègue laisse le trousseau du dépôt accroché à la serrure « pour l’équipe du matin ».",q:"Quel est le problème ?",a:["N’importe qui peut entrer : une clé ne reste jamais sur la porte", "Aucun, si l’équipe du matin arrive avant tous les autres", "Le trousseau risque seulement de s’user ou de se tordre", "Il aurait mieux valu le cacher sous le paillasson d’entrée"],ex:"Ne jamais laisser une clé sur la porte, ni dans un endroit évident comme le paillasson.",ref:"Leçon 9.1"},
{k:"case",s:"Lundi matin, vous constatez que la clé du local des marchandises de valeur a disparu depuis vendredi. Vous pensez la retrouver chez vous ce soir.",q:"Quelle attitude est correcte ?",a:["Signaler la perte tout de suite à l’employeur","Chercher d’abord chez vous et en parler demain","Emprunter la clé d’un collègue en attendant","Ne rien dire tant que rien n’a été volé"],ex:"La perte se signale immédiatement : l’employeur doit pouvoir prendre des mesures préventives sans attendre.",ref:"Leçon 9.1"},
{k:"case",s:"Votre entreprise a des serrures mécaniques. Un apprenti a perdu le passe-partout qui ouvre tous les locaux.",q:"Quelle conséquence financière est probable ?",a:["Remplacer toutes les serrures ouvertes par ce passe-partout","Remplacer seulement la serrure du bureau de l’apprenti","Aucune, il suffit de faire une copie de la clé","Désactiver la clé à distance, sans aucun frais"],ex:"Une clé mécanique ne se désactive pas : toutes les serrures qu’elle ouvre peuvent devoir être changées.",ref:"Leçon 9.1"},
{k:"case",s:"L’entreprise est passée aux badges électroniques. Une collègue a perdu le sien dans le bus.",q:"Quel avantage du système moderne s’applique ici ?",a:["Le badge peut être désactivé sans changer les serrures","Le badge se détruit tout seul hors de l’entreprise","Un badge perdu ne coûte jamais rien à personne","Le badge reste valable, aucune mesure n’est utile"],ex:"Les clés électroniques se désactivent, ce qui évite le remplacement des serrures (mais engendre d’autres coûts).",ref:"Leçon 9.1"},
{k:"case",s:"Un nouveau logisticien découvre qu’il ne peut pas ouvrir le module comptabilité du logiciel de gestion, alors que sa cheffe y a accès.",q:"Comment l’expliquer ?",a:["Les droits d’accès dépendent des responsabilités","Son compte a forcément été piraté","Le logiciel est réservé aux employés âgés","Il doit utiliser le mot de passe de sa cheffe"],ex:"Les droits d’accès sont attribués en fonction des responsabilités de chaque employé.",ref:"Leçon 9.5"},
{k:"case",s:"Votre chef d’équipe, absent, vous demande par téléphone de vous connecter avec son identifiant pour valider une commande urgente.",q:"Quelle réponse est la plus professionnelle ?",a:["Refuser et demander que les droits nécessaires vous soient attribués", "Accepter, puisque c’est votre supérieur direct qui le demande", "Accepter et noter son mot de passe pour une prochaine fois", "Valider avec votre propre compte en contournant le contrôle"],ex:"Chacun travaille avec ses propres droits : utiliser le compte d’un autre fausse le journal des accès et contourne les autorisations.",ref:"Leçon 9.5"},
{k:"case",s:"Le service informatique signale plusieurs tentatives de connexion avec votre identifiant, à 3 heures du matin.",q:"Grâce à quoi ces tentatives ont-elles été repérées ?",a:["Le système enregistre chaque accès","Des collègues surveillent les écrans la nuit","Le mot de passe envoie un SMS au directeur","Le badge d’entrée bloque l’ordinateur"],ex:"Chaque accès est enregistré, ce qui permet de détecter une intrusion non autorisée.",ref:"Leçon 9.5"},
{k:"case",s:"Une personne inconnue en gilet de travail vous suit de près pour franchir la porte sécurisée que vous venez d’ouvrir avec votre badge.",q:"Que faites-vous ?",a:["Lui demander poliment son badge ou la diriger vers l’accueil", "La laisser passer puisqu’elle porte un gilet de l’entreprise", "Lui tenir la porte ouverte pour rester aimable et rapide", "Lui prêter votre badge pour qu’elle puisse circuler seule"],ex:"Chaque personne doit passer avec son propre accès ; un visiteur passe par l’accueil. (Bonne pratique hors support.)",ref:"Hors support · contrôle d’accès"},
{k:"case",s:"Un ami vous propose de graver « Logistik AG – dépôt nord » sur votre porte-clés pour ne plus confondre vos clés.",q:"Pourquoi refusez-vous ?",a:["Une clé perdue identifiée indique où elle peut servir", "La gravure abîme la clé et finit par bloquer la serrure", "Seul le responsable a le droit d’écrire sur une clé", "Une clé gravée n’est plus couverte par l’assurance"],ex:"L’entreprise ne doit pas être identifiable sur la clé, pour des raisons de sécurité.",ref:"Leçon 9.1"},
{k:"case",s:"Vous quittez l’entreprise à la fin du mois. Il vous reste un badge, deux clés et votre compte informatique.",q:"Que doit-il se passer ?",a:["Tout rendre et faire supprimer vos accès","Garder le badge en souvenir, il sera désactivé un jour","Donner les clés à votre successeur sans le dire","Garder votre compte actif au cas où"],ex:"Les accès suivent les responsabilités : sans fonction, plus d’accès. (Bonne pratique hors support.)",ref:"Hors support · gestion des accès"}
]},

/* ============ 2 · A2.3 SÉCURITÉ INFORMATIQUE ============ */
{code:"A2.3", t:"Sécurité informatique", g:"J’explique comment j’utilise systématiquement les moyens informatiques et comment je protège l’entreprise des dangers liés notamment à l’utilisation d’Internet (sécurité des données, attaques de pirates, virus, phishing, etc.). (C2)", col:"indigo", ic:"lock",
ch:[
{k:"num",q:"Selon le cours, quelle est la longueur minimale d’un mot de passe efficace ?",n:12,tol:0,u:"caractères",ex:"Le cours fixe une longueur minimale de 12 caractères.",ref:"Leçon 9.5.1"},
{k:"num",q:"Selon le cours, il est recommandé de changer son mot de passe au moins tous les combien de mois ?",n:3,tol:0,u:"mois",ex:"Le cours recommande un changement au moins tous les trois mois.",ref:"Leçon 9.5.1"},
{k:"multi",q:"Quelles règles un mot de passe sûr doit-il respecter selon le cours ?",good:["Au moins 12 caractères","Majuscules et minuscules","Chiffres et caractères spéciaux","Un mot de passe unique par compte"],bad:["Contenir sa date de naissance","Être identique sur tous les comptes"],ex:"Pas d’information personnelle et un mot de passe différent pour chaque compte.",ref:"Leçon 9.5.1"},
{k:"tf",q:"« Marie1990 » est un bon mot de passe, car il contient une majuscule, des minuscules et des chiffres.",v:false,ex:"Il est trop court (9 caractères) et contient des informations personnelles (prénom, année).",ref:"Leçon 9.5.1"},
{k:"qcm",q:"Lequel de ces mots de passe respecte le mieux les règles du cours ?",a:["T4p!s-Rouge#Quai27", "azerty12345678", "Logistique2024!", "Pierre-12.05.1998"],ex:"Long, mélangé et sans séquence ni information personnelle. « azerty » est une séquence prévisible, la date de naissance est personnelle.",ref:"Leçon 9.5.1"},
{k:"fill",q:"Pour une sécurité renforcée, activez l’authentification à ___ facteurs.",a:["deux","un seul","dix","aucun"],ex:"L’authentification à deux facteurs ajoute une seconde preuve au mot de passe.",ref:"Leçon 9.5.1"},
{k:"qcm",q:"Quel outil le cours recommande-t-il pour gérer des mots de passe uniques ?",a:["Un gestionnaire de mots de passe","Un carnet collé sous le clavier","Le même mot de passe partout","Un fichier texte sur le bureau"],ex:"Le cours conseille un gestionnaire de mots de passe (comparateur en lien dans la leçon).",ref:"Leçon 9.5.1"},
{k:"match",q:"Associez chaque raison du cours à ce qu’elle évite.",p:[["Contre la force brute","Deviner le code avec un programme automatique"],["Contre le piratage de compte","Perte de données sensibles d’un compte compromis"],["Mot de passe unique","Effet domino après la fuite d’un site"],["Contre le vol d’identité","Usage frauduleux de vos informations"]],ex:"Le cours donne quatre raisons de respecter les normes des mots de passe.",ref:"Leçon 9.5.1"},
{k:"qcm",q:"Qu’est-ce qu’une attaque par force brute ?",a:["Essayer automatiquement de très nombreuses combinaisons", "Casser l’ordinateur pour voler physiquement le disque dur", "Menacer un employé pour qu’il révèle son code d’accès", "Couper le courant du serveur pour bloquer l’entreprise"],ex:"Les attaquants utilisent des méthodes automatisées pour deviner ou craquer les codes d’accès.",ref:"Leçon 9.5.1"},
{k:"tf",q:"Utiliser le même mot de passe sur plusieurs comptes augmente le risque en cas de fuite de données sur un site.",v:true,ex:"Avec des mots de passe uniques, une fuite sur un site ne compromet pas les autres comptes.",ref:"Leçon 9.5.1"},
{k:"odd",q:"Trouvez l’intrus : ces pratiques renforcent la sécurité, sauf une.",a:["Utiliser la séquence « 123456 » partout","Activer l’authentification à deux facteurs","Utiliser un gestionnaire de mots de passe","Changer régulièrement de mot de passe"],ex:"Les séquences simples ou prévisibles sont à exclure.",ref:"Leçon 9.5.1"},
{k:"qcm",q:"À quoi sert un site comme haveibeenpwned.com, cité dans la leçon ?",a:["Vérifier si votre e-mail figure dans une fuite de données", "Créer une adresse e-mail anonyme pour vos achats en ligne", "Bloquer automatiquement tous les virus de l’ordinateur", "Changer régulièrement votre mot de passe à votre place"],ex:"La leçon le présente sous « Votre e-mail est-il en danger ? ».",ref:"Leçon 9.5 · liens utiles"},
{k:"qcm",q:"Selon le cours, que garantit le respect des normes de mots de passe ?",a:["La confidentialité, l’intégrité et la disponibilité des données", "La rapidité du réseau et des imprimantes de l’entreprise", "La gratuité de tous les logiciels utilisés dans l’entreprise", "La suppression des sauvegardes devenues inutiles au quotidien"],ex:"Le cours conclut : confidentialité, intégrité et disponibilité des données, et confiance des utilisateurs.",ref:"Leçon 9.5.1"},
{k:"tf",q:"L’authentification à deux facteurs demande, en plus du mot de passe, une seconde preuve, par exemple un code reçu sur le téléphone.",v:true,ex:"Même si le mot de passe est volé, le pirate ne peut pas se connecter sans le second facteur.",ref:"Leçon 9.5.1"},
{k:"multi",q:"Quels indices peuvent signaler un e-mail de phishing ?",good:["Urgence ou menace pour vous presser","Adresse d’expéditeur inhabituelle","Demande de données de carte bancaire","Lien vers un site au nom étrange"],bad:["Message attendu d’un collègue, sans lien ni pièce jointe"],img:"mail",ex:"Pression, expéditeur douteux, demande de données sensibles et lien suspect sont les signes classiques. (Hors support.)",ref:HS_NCSC},
{k:"qcm",q:"Dans cet e-mail, quel élément révèle le mieux une tentative de phishing ?",a:["L’expéditeur et le lien utilisent des domaines inhabituels", "Le message est rédigé en français et commence par « Cher client »", "L’adresse du destinataire de l’e-mail se termine par .ch", "Le texte du message contient un bouton de couleur bleue"],img:"mail",ex:"Les domaines « .xyz » et « .top » sans rapport avec un vrai transporteur trahissent la tentative. (Hors support.)",ref:HS_NCSC},
{k:"sort",q:"Comportement sûr ou risqué ? Classez.",c:["Sûr","Risqué"],it:[["Verrouiller l’écran en quittant son poste",0],["Brancher une clé USB trouvée sur le parking",1],["Installer les mises à jour validées par l’informatique",0],["Noter son mot de passe sur un post-it",1],["Vérifier l’expéditeur avant d’ouvrir une pièce jointe",0],["Désactiver l’antivirus qui ralentit le PC",1]],ex:"Ces réflexes complètent les règles des mots de passe du cours. (Hors support.)",ref:HS_NCSC},
{k:"match",q:"Associez chaque menace à sa description.",p:[["Phishing","Faux message pour voler des identifiants"],["Virus","Programme qui infecte et endommage les fichiers"],["Rançongiciel","Chiffre les données et exige une rançon"],["Pirate","Personne qui s’introduit sans droit dans un système"]],ex:"Les menaces citées dans l’objectif A2.3. (Définitions hors support.)",ref:HS_NCSC},
{k:"order",q:"Vous avez saisi votre mot de passe sur une page suspecte. Remettez les réactions dans l’ordre.",a:["Ne plus rien saisir sur la page ouverte","Avertir immédiatement le service informatique","Changer le mot de passe concerné","Surveiller le compte les jours suivants"],ex:"Stopper, alerter, changer, surveiller : plus la réaction est rapide, plus le dommage est limité. (Hors support.)",ref:HS_NCSC},
{k:"case",s:"Un collègue choisit comme mot de passe le nom de son chien suivi de son année de naissance.",q:"Quelle règle ne respecte-t-il pas ?",a:["Éviter les informations personnelles","Changer de mot de passe chaque jour","Utiliser uniquement des chiffres","Ne jamais utiliser de minuscules"],ex:"Les informations personnelles (noms, dates) sont faciles à deviner.",ref:"Leçon 9.5.1"},
{k:"case",s:"Pour ne rien oublier, une apprentie utilise le même mot de passe pour sa messagerie, le logiciel de stock et son compte de boutique en ligne.",q:"Quel risque court-elle ?",a:["Une fuite sur un seul site ouvre tous ses comptes", "Aucun, tant que le mot de passe dépasse 12 caractères", "Son ordinateur va ralentir à force de se connecter", "Elle ne pourra plus recevoir d’e-mails professionnels"],ex:"Un mot de passe unique par compte limite les dégâts d’une fuite de données.",ref:"Leçon 9.5.1"},
{k:"case",s:"Un collègue a collé son mot de passe sur l’écran du poste de saisie des commandes « pour l’équipe de nuit ».",q:"Que conseillez-vous ?",a:["Retirer la note et faire créer un accès par utilisateur", "Recopier la note dans un tiroir fermé à clé au même poste", "Réécrire le mot de passe plus petit pour qu’on ne le lise pas", "Laisser la note, puisqu’elle ne sert qu’à l’équipe de nuit"],ex:"Chaque utilisateur a son propre accès, attribué selon ses responsabilités ; un mot de passe ne s’affiche pas.",ref:"Leçon 9.5"},
{k:"case",s:"Vous trouvez une clé USB marquée « Salaires 2026 » sur le parking de l’entreprise.",q:"Que faites-vous ?",a:["La remettre à l’informatique sans la brancher", "La brancher pour retrouver son propriétaire", "La brancher sur un vieux PC de l’entrepôt", "La garder pour vous ou la jeter à la poubelle"],ex:"Une clé USB inconnue peut contenir un programme malveillant : on ne la branche jamais. (Hors support.)",ref:HS_NCSC},
{k:"case",s:"Un « technicien Microsoft » vous appelle et demande votre mot de passe pour réparer un problème urgent sur votre poste.",q:"Quelle réaction est correcte ?",a:["Ne jamais le donner et prévenir l’informatique","Le donner, car il connaît le nom de l’entreprise","Le donner seulement s’il rappelle une seconde fois","L’envoyer par e-mail plutôt que par téléphone"],ex:"Aucun service sérieux ne demande votre mot de passe. (Hors support.)",ref:HS_NCSC},
{k:"case",s:"Le logiciel de gestion d’entrepôt propose une mise à jour de sécurité validée par le service informatique.",q:"Pourquoi l’installer ?",a:["Elle corrige des failles utilisables par des pirates","Elle rend le mot de passe inutile","Elle supprime l’obligation de sauvegarder","Elle accélère seulement l’impression des étiquettes"],ex:"Les mises à jour ferment des failles connues des attaquants. (Hors support.)",ref:HS_NCSC},
{k:"case",s:"Un matin, tous les fichiers du serveur sont illisibles et un message réclame un paiement en cryptomonnaie pour les récupérer.",q:"De quel type d’attaque s’agit-il ?",a:["Un rançongiciel","Une attaque par force brute","Une panne d’imprimante","Un phishing par SMS"],ex:"Le rançongiciel chiffre les données et exige une rançon ; on alerte l’informatique et on ne paie pas. (Hors support.)",ref:HS_NCSC},
{k:"case",s:"Vous devez quitter votre poste dix minutes pour aider au quai de chargement. Votre session du logiciel de stock est ouverte.",q:"Que faites-vous ?",a:["Verrouiller l’écran avant de partir","Laisser la session ouverte, c’est rapide","Éteindre seulement l’écran","Demander au chauffeur de surveiller le PC"],ex:"Une session ouverte permet à n’importe qui d’agir sous votre nom. (Hors support.)",ref:HS_NCSC},
{k:"case",s:"Votre entreprise active l’authentification à deux facteurs. Un collègue râle : « Mon mot de passe suffit ! »",q:"Quel argument lui donnez-vous ?",a:["Même avec son mot de passe volé, un pirate ne pourra pas se connecter", "Il n’aura plus jamais besoin de changer son mot de passe ensuite", "Cela remplace l’antivirus installé sur son ordinateur de travail", "Cela l’autorise à partager son mot de passe avec son équipe"],ex:"Le second facteur bloque l’accès même si le mot de passe est connu.",ref:"Leçon 9.5.1"},
{k:"case",s:"La réception reçoit un e-mail d’un transporteur inconnu : il exige CHF 2.99 sous 24 heures pour débloquer un colis, avec un bouton « Payer maintenant ».",q:"Quelle est la bonne réaction ?",a:["Ne pas cliquer et signaler l’e-mail à l’informatique","Payer les 2.99 francs, le montant est faible","Répondre pour demander plus d’informations","Transférer l’e-mail à tous les collègues pour avis"],img:"mail",ex:"Urgence, petit montant et demande de carte bancaire : c’est du phishing. On le signale (en Suisse aussi au NCSC). (Hors support.)",ref:HS_NCSC},
{k:"case",s:"Un SMS vous informe qu’un colis attend le paiement de « frais de 1.50 CHF », avec un lien raccourci.",q:"Comment le traiter ?",a:["Ne pas cliquer, supprimer ou signaler le message", "Cliquer sur le lien pour vérifier si le colis existe", "Payer les frais, le montant est vraiment symbolique", "Répondre « STOP » pour ne plus recevoir de messages"],ex:"Le phishing passe aussi par SMS ; répondre confirme que votre numéro est actif. (Hors support.)",ref:HS_NCSC}
]},

/* ============ 3 · B1.5 SECRETS ET PROTECTION DES DONNÉES ============ */
{code:"B1.5", t:"Secrets et protection des données", g:"J’explique les bases et les effets de la protection des données et de la vie privée ainsi que du secret postal. (C2)", col:"violet", ic:"mailx",
ch:[
{k:"qcm",q:"Quel article du Code pénal sanctionne la violation du secret de l’écriture ?",a:["Art. 179 CP","Art. 321ter CP","Art. 321a CO","Art. 6 LPD"],ex:"L’art. 179 CP, sous « Infractions contre l’honneur et le domaine secret ou privé ».",ref:"Leçon 9.2 · CP 179"},
{k:"qcm",q:"Quel article du Code pénal réprime la violation du secret postal ?",a:["Art. 321ter CP","Art. 179 CP","Art. 162 CP","Art. 321a CO"],ex:"Art. 321ter CP : violation du secret des postes et des télécommunications.",ref:"Leçon 9.3 · CP 321ter"},
{k:"qcm",q:"Où le secret des affaires de l’employé est-il réglé, selon le cours ?",a:["Dans le Code des obligations (art. 321a CO)","Dans la loi sur la circulation routière","Dans le règlement interne de la Poste","Dans la Constitution cantonale"],ex:"Le devoir de diligence et de fidélité de l’art. 321a CO inclut la discrétion sur les secrets d’affaires.",ref:"Leçon 9.4 · CO 321a"},
{k:"tf",q:"Le secret de l’écriture ne s’applique qu’à la sphère professionnelle.",v:false,ex:"Il s’applique aussi à la sphère privée : les particuliers ne sont pas concernés par le courrier des autres.",ref:"Leçon 9.2"},
{k:"qcm",q:"Qu’est-ce qu’un délit sur plainte ?",a:["Les autorités enquêtent seulement si la personne lésée le demande", "Les autorités enquêtent dès qu’elles ont connaissance des faits", "Seul l’employeur de l’auteur peut déposer une plainte pénale", "Le délit est jugé en interne par l’entreprise elle-même"],ex:"À l’inverse, un délit poursuivi d’office oblige les autorités à enquêter de leur propre chef.",ref:"Leçon 9.2"},
{k:"match",q:"Associez chaque notion à sa définition.",p:[["Délit sur plainte","Enquête à la demande de la personne lésée"],["Délit poursuivi d’office","Enquête dès que l’autorité apprend les faits"],["Secret de l’écriture","Protège le contenu des plis et colis fermés"],["Secret postal","Protège aussi l’expéditeur et le destinataire"]],ex:"Le secret postal va au-delà du contenu : il protège aussi l’identité des personnes et la fréquence des envois.",ref:"Leçons 9.2 et 9.3"},
{k:"multi",q:"Que protège le secret postal ?",good:["Le contenu des envois","L’identité de l’expéditeur","L’identité du destinataire","La fréquence des envois"],bad:["Les tarifs officiels de la Poste","L’adresse publique d’un bureau de poste"],ex:"Le secret postal empêche toute divulgation de l’identité des personnes ou de la fréquence des envois.",ref:"Leçon 9.3"},
{k:"fill",q:"Le secret postal va au-delà de la simple confidentialité des ___.",a:["lettres","factures","timbres","tarifs"],ex:"Il englobe aussi la protection de l’expéditeur et du destinataire.",ref:"Leçon 9.3"},
{k:"tf",q:"Le secret postal doit être respecté même après la fin de l’emploi.",v:true,ex:"La violation reste punissable après la fin de l’emploi (art. 321ter al. 3 CP).",ref:"Leçon 9.3 · CP 321ter"},
{k:"multi",q:"Quelles informations le cours cite-t-il comme hautement privées ?",good:["Les actes judiciaires","Les notifications de paiement","Le versement de l’AVS"],bad:["L’horaire d’ouverture d’un dépôt","La météo du jour"],ex:"Le cours donne ces exemples : actes judiciaires, notifications de paiement, versement de l’AVS.",ref:"Leçon 9.3"},
{k:"qcm",q:"Pendant combien de temps l’employé doit-il garder les secrets de fabrication et d’affaires ?",a:["Pendant le contrat et après, si l’intérêt de l’employeur l’exige", "Seulement pendant le temps d’essai, puis le secret est levé", "Uniquement pendant ses heures de travail effectives", "Jusqu’à la fin de l’année civile où le contrat se termine"],ex:"L’obligation de discrétion continue après la fin du contrat, dans la mesure où les intérêts légitimes de l’employeur l’exigent.",ref:"Leçon 9.4 · CO 321a al. 4"},
{k:"fill",q:"Le travailleur exécute son travail avec soin et sauvegarde ___ les intérêts légitimes de l’employeur.",a:["fidèlement","partiellement","occasionnellement","librement"],ex:"C’est le devoir de diligence et de fidélité (art. 321a al. 1 CO).",ref:"Leçon 9.4 · CO 321a"},
{k:"sort",q:"Secret postal ou secret des affaires ? Classez.",c:["Secret postal","Secret des affaires"],it:[["Identité du destinataire d’un recommandé",0],["Recette de fabrication d’un produit",1],["Fréquence des envois d’un client",0],["Prix négociés avec les fournisseurs",1],["Contenu d’une lettre transportée",0],["Projet de nouveau site logistique",1]],ex:"Le secret postal protège les envois et les personnes ; le secret des affaires protège les informations de l’employeur.",ref:"Leçons 9.3 et 9.4"},
{k:"odd",q:"Trouvez l’intrus : ces éléments relèvent d’un secret protégé, sauf un.",a:["L’adresse publique du siège de l’entreprise","Le contenu d’un colis fermé","L’expéditeur d’un acte judiciaire","Les marges commerciales de l’employeur"],ex:"L’adresse du siège est publique ; les trois autres sont protégés (secret de l’écriture, secret postal, secret des affaires).",ref:"Leçons 9.2 à 9.4"},
{k:"order",q:"Un collègue ouvre sans droit un pli fermé destiné à une autre personne. Remettez la suite dans l’ordre (art. 179 CP).",a:["Le pli est ouvert sans droit","Le destinataire découvre l’ouverture","Le destinataire dépose plainte","Les autorités ouvrent une enquête","Le juge peut prononcer une amende"],ex:"C’est un délit sur plainte : sans plainte de la personne lésée, pas d’enquête.",ref:"Leçon 9.2 · CP 179"},
{k:"qcm",q:"Depuis quand la nouvelle loi fédérale sur la protection des données (nLPD) est-elle en vigueur ?",a:["Depuis le 1er septembre 2023","Depuis le 1er janvier 2000","Depuis le 1er janvier 2026","Depuis le 1er juillet 1992"],ex:"La LPD totalement révisée est entrée en vigueur le 1er septembre 2023, sans période transitoire. (Hors support.)",ref:HS_LPD},
{k:"multi",q:"Quels sont des principes de traitement des données selon la nLPD ?",good:["Licéité","Bonne foi","Proportionnalité","Finalité","Sécurité"],bad:["Rentabilité","Publicité"],ex:"Art. 6 et 8 LPD : licéité, bonne foi, proportionnalité, finalité, transparence, exactitude et sécurité. (Hors support.)",ref:HS_LPD},
{k:"tf",q:"La nLPD protège les données des personnes physiques, mais plus celles des personnes morales (entreprises).",v:true,ex:"Depuis 2023, seules les données des personnes physiques sont protégées par la LPD. (Hors support.)",ref:HS_LPD},
{k:"case",s:"Au service courrier interne, une collègue remarque une enveloppe de l’Office des poursuites adressée à un collègue et en parle à la pause.",q:"Quel principe enfreint-elle ?",a:["La discrétion sur l’expéditeur et le destinataire d’un envoi", "Aucun principe, puisqu’elle n’a pas ouvert l’enveloppe", "Uniquement les règles de politesse entre collègues", "Le secret des affaires propre à l’Office des poursuites"],ex:"La protection va au-delà du contenu : l’identité de l’expéditeur et du destinataire ne se divulgue pas.",ref:"Leçon 9.3"},
{k:"case",s:"Lors de votre tournée, vous remarquez qu’un client reçoit chaque mois un courrier de la caisse AVS. Un voisin vous demande s’il touche une rente.",q:"Que répondez-vous ?",a:["Vous ne donnez aucune information sur le courrier des clients", "Vous confirmez, puisque ce n’est pas vraiment un secret", "Vous répondez seulement si ce voisin est aussi votre ami", "Vous lui conseillez de regarder lui-même dans la boîte"],ex:"Le cours cite précisément le versement de l’AVS comme information confidentielle.",ref:"Leçon 9.3"},
{k:"case",s:"Votre colocataire ouvre « par curiosité » une lettre fermée qui vous est adressée.",q:"Le secret de l’écriture s’applique-t-il ?",a:["Oui, il s’applique aussi à la sphère privée","Non, il ne vise que les employés de la Poste","Non, il ne concerne que les colis","Oui, mais seulement pour une lettre d’un tribunal"],ex:"Le secret de l’écriture vaut aussi entre particuliers.",ref:"Leçon 9.2 · CP 179"},
{k:"case",s:"Un ancien employé d’un centre de tri postal, parti depuis deux ans, raconte quels voisins reçoivent des actes judiciaires.",q:"Peut-il être poursuivi ?",a:["Oui, la violation reste punissable après l’emploi", "Non, le secret prend fin avec le contrat de travail", "Non, car il ne travaille plus pour la Poste", "Seulement s’il a lui-même ouvert les envois"],ex:"Le secret postal continue de s’appliquer après la fin de l’emploi.",ref:"Leçon 9.3 · CP 321ter"},
{k:"case",s:"Une cliente découvre qu’un employé de la réception a ouvert un pli fermé qui lui était destiné, mais elle ne veut pas porter plainte.",q:"Que se passe-t-il au niveau pénal (art. 179 CP) ?",a:["Rien : c’est un délit sur plainte","La police enquête de toute façon","L’employé est automatiquement emprisonné","L’entreprise paie une amende fixe"],ex:"Sans plainte de la personne lésée, les autorités n’enquêtent pas.",ref:"Leçon 9.2 · CP 179"},
{k:"case",s:"Au café, un ami vous demande combien votre entreprise facture le stockage à son plus gros client.",q:"Que faites-vous ?",a:["Vous refusez : c’est un secret d’affaires","Vous répondez, puisque c’est un ami","Vous donnez seulement un chiffre approximatif","Vous répondez si votre temps d’essai est terminé"],ex:"Les informations commerciales de l’employeur sont confidentielles (art. 321a CO).",ref:"Leçon 9.4 · CO 321a"},
{k:"case",s:"Vous partez chez un concurrent. Votre nouveau chef vous demande la liste des clients de votre ancien employeur.",q:"Comment réagir ?",a:["Refuser : la discrétion continue après le contrat","Accepter, l’ancien contrat ne vous lie plus","Accepter si la liste date de plus d’un an","La donner oralement plutôt que par écrit"],ex:"Le devoir de garder les secrets d’affaires subsiste après la fin du contrat.",ref:"Leçon 9.4 · CO 321a al. 4"},
{k:"case",s:"Sur un réseau social, un apprenti publie un long message qui critique ouvertement son entreprise et ses chefs.",q:"Que recommande le cours ?",a:["Faire preuve de retenue et éviter les critiques publiques", "Critiquer publiquement pour faire bouger les choses vite", "Publier seulement sous un pseudonyme pour rester discret", "Mentionner l’entreprise pour qu’elle réponde publiquement"],ex:"Le cours recommande la retenue : une critique publique laisse une impression négative.",ref:"Leçon 9.4"},
{k:"case",s:"Votre entreprise note la date de naissance de chaque visiteur du dépôt « au cas où », sans lui dire pourquoi.",q:"Quels principes de la nLPD sont touchés ?",a:["La proportionnalité et la bonne foi (transparence)", "Uniquement la rentabilité de l’entreprise", "Aucun, les visiteurs ne sont pas des clients", "Seulement le secret postal et celui des affaires"],ex:"On ne collecte que les données nécessaires, pour un but reconnaissable par la personne. (Hors support.)",ref:HS_LPD},
{k:"case",s:"Un chauffeur-livreur photographie un bon de livraison signé par un client et le publie sur un groupe de discussion pour plaisanter sur sa signature.",q:"Quel est le problème ?",a:["Il divulgue des données personnelles sans motif","Aucun, une signature n’est pas une donnée","Seule la qualité de la photo pose problème","C’est autorisé dans un groupe privé"],ex:"Nom, adresse et signature sont des données personnelles : leur diffusion sans motif viole la vie privée du client. (Hors support.)",ref:HS_LPD}
]},

/* ============ 4 · B1.6 CONSÉQUENCES EN PRATIQUE ============ */
{code:"B1.6", t:"Conséquences en pratique", g:"J’explique les conséquences des dispositions légales relatives à la protection des données et de la vie privée et au secret postal pour l’activité pratique, ainsi qu’une conséquence pour le client et l’entreprise en cas de violation. (C2)", col:"coral", ic:"balance",
ch:[
{k:"pickimg",q:"Le service courrier peut ouvrir cette enveloppe sans hésiter. Laquelle ?",a:["env_a","env_b","env_c","env_d"],ex:"Adressée à l’entreprise seule : elle peut être ouverte.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"pickimg",q:"Laquelle ne doit JAMAIS être ouverte par le service courrier ?",a:["env_d","env_a","env_b","env_c"],ex:"La mention « Personnel/confidentiel » interdit toute ouverture.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"pickimg",q:"Laquelle ne s’ouvre que si M. Gugger l’a expressément souhaité ?",a:["env_c","env_a","env_d"],ex:"Le nom de la personne figure avant l’entreprise : on n’ouvre que si M. Gugger l’a expressément souhaité.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"pickimg",q:"Laquelle peut être ouverte sur instruction, sans avis contraire ?",a:["env_b","env_c","env_d"],ex:"Entreprise en premier, « À l’attention de » ensuite : ouverture sur instruction, sans avis contraire.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"match",q:"Associez chaque enveloppe à sa règle d’ouverture.",p:[["A · EnterSite AG","Ouvrir"],["B · À l’attention de R. Gugger","Ouvrir sur instruction, sans avis contraire"],["C · Monsieur Reto Gugger, EnterSite AG","Seulement si M. Gugger l’a souhaité"],["D · Personnel/confidentiel","Ne jamais ouvrir"]],img:"env",ex:"Plus la personne est mise en avant dans l’adresse, plus le courrier est considéré comme personnel.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"sort",q:"Le service courrier peut-il ouvrir ce courrier ? Classez.",c:["Peut être ouvert","Pas sans accord du destinataire"],it:[["Adresse : EnterSite AG seule",0],["EnterSite AG, à l’attention de R. Gugger",0],["Monsieur R. Gugger, EnterSite AG",1],["Mention « Personnel/confidentiel »",1]],img:"env",ex:"A et B peuvent être ouvertes (B sur instruction) ; C seulement si M. Gugger l’a souhaité ; D jamais.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"tf",q:"Quand le nom de la personne figure avant celui de l’entreprise, la lettre est considérée comme personnelle.",v:true,ex:"« Monsieur Reto Gugger, EnterSite AG » : on n’ouvre que si M. Gugger l’a expressément souhaité.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"tf",q:"Le secret de l’écriture concerne aussi les collaborateurs d’un service de courrier interne à l’entreprise.",v:true,ex:"Le contenu des lettres et colis ne les concerne pas, pas plus que les employés de la Poste.",ref:"Leçon 9.2"},
{k:"qcm",q:"Quelle sanction l’art. 179 CP prévoit-il pour la violation du secret de l’écriture ?",a:["Une amende, sur plainte","Une peine de prison de dix ans","Un simple avertissement oral","Aucune, c’est une règle morale"],ex:"Art. 179 CP : « est, sur plainte, puni d’une amende ».",ref:"Leçon 9.2 · CP 179"},
{k:"qcm",q:"Que risque un employé d’un service postal qui viole le secret postal ?",a:["Une peine privative de liberté ou une peine pécuniaire", "Seulement un blâme écrit de son chef de service", "Une amende d’ordre de 20 francs, payable sur place", "Rien du tout s’il a quitté son emploi depuis"],ex:"Le cours parle de peines de prison ou d’amendes, même après la fin de l’emploi (art. 321ter CP).",ref:"Leçon 9.3 · CP 321ter"},
{k:"num",q:"Peine privative de liberté maximale, en années, prévue par l’art. 321ter CP ?",n:3,tol:0,u:"ans",ex:"Art. 321ter al. 1 CP : peine privative de liberté de trois ans au plus ou peine pécuniaire. (Chiffre hors support.)",ref:"Hors support · CP 321ter al. 1"},
{k:"num",q:"Montant maximal, en francs, de l’amende prévue par la nLPD pour certaines violations intentionnelles ?",n:250000,tol:0,u:"CHF",ex:"La nLPD prévoit des amendes jusqu’à CHF 250 000, infligées à la personne responsable. (Hors support.)",ref:HS_LPD},
{k:"qcm",q:"Selon le cours, que peut faire l’employeur contre un employé qui ne garde pas les secrets d’affaires ?",a:["Le dénoncer","Lui retirer son droit de vote","Le priver de ses vacances légales","Rien, la loi ne le prévoit pas"],ex:"Celui qui ne respecte pas cette règle peut être dénoncé par son employeur.",ref:"Leçon 9.4"},
{k:"multi",q:"Quelles conséquences une violation de la protection des données peut-elle avoir pour l’entreprise ?",good:["Perte de confiance des clients","Atteinte à son image","Plainte ou sanction pénale","Perte de clients ou de contrats"],bad:["Hausse automatique de ses ventes"],ex:"La confiance est au cœur de l’activité logistique : une fuite la détruit vite.",ref:"Objectif B1.6"},
{k:"multi",q:"Quelles conséquences pour le client dont les données ont été divulguées ?",good:["Atteinte à sa vie privée","Divulgation d’informations sensibles (poursuites, argent)","Risque de fraude ou d’usurpation d’identité"],bad:["Réduction de ses impôts","Livraison plus rapide de ses colis"],ex:"Le cours rappelle que des mots de passe faibles exposent à la fraude et au vol d’identité ; une divulgation touche la vie privée.",ref:"Leçons 9.3 et 9.5"},
{k:"odd",q:"Trouvez l’intrus : ces gestes respectent le secret au quotidien, sauf un.",a:["Commenter le courrier d’un client avec un voisin","Remettre une lettre fermée sans la lire","Ne pas parler des clients hors du travail","Transmettre un pli confidentiel sans l’ouvrir"],ex:"Le courrier des clients ne se commente jamais avec des tiers.",ref:"Leçon 9.3"},
{k:"order",q:"Une enveloppe « Personnel/confidentiel » a été ouverte par erreur au courrier interne. Remettez les actions dans l’ordre.",a:["Arrêter immédiatement de lire","Refermer et noter « ouvert par erreur »","Remettre l’envoi au destinataire en l’informant"],ex:"On limite la prise de connaissance, on signale l’erreur et on remet l’envoi. (Bonne pratique hors support.)",ref:"Hors support · bonne pratique"},
{k:"case",s:"Au service courrier d’EnterSite AG, vous triez une lettre adressée « Monsieur Reto Gugger, EnterSite AG ». M. Gugger n’a donné aucune consigne.",q:"Que faites-vous ?",a:["Vous la lui transmettez fermée","Vous l’ouvrez pour la classer au bon service","Vous l’ouvrez puis la refermez soigneusement","Vous la renvoyez à l’expéditeur"],img:"env",ex:"Enveloppe C : on n’ouvre que si M. Gugger l’a expressément souhaité.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"case",s:"Votre cheffe vous a demandé d’ouvrir le courrier de l’entreprise pendant ses vacances. Une lettre « Personnel/confidentiel » lui est adressée.",q:"Que faites-vous ?",a:["Vous la gardez fermée pour son retour","Vous l’ouvrez puisqu’elle vous l’a demandé","Vous la faites ouvrir par un collègue","Vous la lisez sans la sortir de l’enveloppe"],ex:"« Personnel/confidentiel » : ne jamais ouvrir. La consigne vise le courrier de l’entreprise.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"case",s:"Une lettre arrive adressée « EnterSite AG, à l’attention de Reto Gugger ». Aucune consigne contraire n’existe.",q:"Selon le tableau du cours, que faire ?",a:["Elle peut être ouverte sur instruction","Elle ne doit jamais être ouverte","Seulement si M. Gugger l’a souhaité","La retourner à l’expéditeur"],ex:"Enveloppe B : sans avis contraire, elle s’ouvre sur instruction.",ref:"Leçon 9.2 · tableau des adresses"},
{k:"case",s:"Un livreur raconte au restaurant qu’un client reçoit beaucoup de recommandés de l’Office des poursuites. Le client l’apprend.",q:"Quelle conséquence pour le client ?",a:["Sa situation financière privée est exposée","Aucune, les recommandés ne sont pas confidentiels","Il obtient un délai de paiement","Ses poursuites sont annulées"],ex:"Le secret postal protège précisément l’identité de l’expéditeur et les actes judiciaires.",ref:"Leçon 9.3"},
{k:"case",s:"Un client découvre qu’un livreur a divulgué ses envois de l’Office des poursuites et raconte l’affaire sur les réseaux sociaux.",q:"Quelle conséquence l’entreprise de livraison risque-t-elle ?",a:["Perte de confiance, atteinte à l’image, départ de clients", "Une hausse de ses commandes grâce à la publicité gratuite", "Aucune, car seul le livreur est concerné par l’affaire", "Une subvention publique pour former mieux le livreur"],ex:"L’entreprise subit la perte de confiance, en plus de la procédure contre l’employé.",ref:"Objectif B1.6"},
{k:"case",s:"Un employé de bureau d’une entreprise de construction ouvre par curiosité un colis fermé adressé à un collègue.",q:"Quel article peut s’appliquer ?",a:["Art. 179 CP, secret de l’écriture","Art. 321a CO, fidélité du client","Art. 162 CP, secret de fabrication","Aucun, entre collègues c’est permis"],ex:"Ouvrir sans droit un pli ou colis fermé pour en connaître le contenu : art. 179 CP.",ref:"Leçon 9.2 · CP 179"},
{k:"case",s:"Une employée de la Poste raconte à sa famille qu’un voisin reçoit régulièrement des envois d’une clinique.",q:"Quel risque pénal court-elle ?",a:["Une peine privative de liberté ou pécuniaire (art. 321ter CP)", "Une simple amende d’ordre de 40 francs (art. 179 CP)", "Aucun risque, puisqu’elle n’a ouvert aucun envoi", "Uniquement un avertissement interne de son employeur"],ex:"Divulguer des renseignements sur les relations postales d’un client suffit, même sans ouvrir l’envoi.",ref:"Leçon 9.3 · CP 321ter"},
{k:"case",s:"Un magasinier transmet à un concurrent les prix d’achat négociés par son employeur.",q:"Quelle conséquence est possible ?",a:["Son employeur peut le dénoncer","Aucune, les prix d’achat sont publics","Il reçoit une prime de son employeur","Seul le concurrent est punissable"],ex:"Violation du secret des affaires (art. 321a CO) : l’employeur peut le dénoncer.",ref:"Leçon 9.4"},
{k:"case",s:"Pendant une visite de l’entrepôt, des élèves photographient un écran qui affiche les noms, adresses et commandes de clients.",q:"Quelle mesure pratique aurait évité le problème ?",a:["Masquer ou verrouiller les écrans avec des données clients", "Interdire désormais toute visite de l’entreprise", "Afficher les données en plus petit sur les écrans", "Rien, car ces données ne sont pas des données personnelles"],ex:"La sécurité des données passe par des gestes simples au poste de travail. (Hors support.)",ref:HS_LPD},
{k:"case",s:"Un collègue jette des bons de livraison avec noms, adresses et signatures de clients dans la poubelle du quai, accessible à tous.",q:"Que lui dites-vous ?",a:["Ces documents se détruisent de façon sûre (déchiqueteuse)", "C’est correct, ce sont de vieux documents sans valeur", "Il faut les recycler avec le carton ordinaire du quai", "Il suffit de les plier en deux avant de les jeter"],ex:"Des données personnelles se détruisent de manière sûre quand elles ne sont plus utiles. (Hors support.)",ref:HS_LPD}
]},

/* ============ 5 · D5.3 PERSONNES AUTORISÉES À RECEVOIR ============ */
{code:"D5.3", t:"Personnes autorisées à recevoir", g:"J’explique les conditions cadres légales relatives aux personnes autorisées à recevoir des marchandises à livrer. (C2)", col:"amber", ic:"parcel",
ch:[
{k:"qcm",q:"À qui le logisticien remet-il les marchandises livrées ?",a:["À une personne habilitée à les recevoir","À la première personne présente à l’adresse","À n’importe quel voisin disponible","Au chauffeur suivant de la tournée"],ex:"Compétence d5 : remettre les marchandises de manière compétente à une personne habilitée.",ref:"Plan de formation · compétence d5"},
{k:"tf",q:"Une personne vivant dans le même ménage peut retirer un envoi ordinaire sans procuration.",v:true,ex:"Les personnes du même ménage n’ont pas besoin de procuration (sauf actes de poursuite). (Hors support.)",ref:HS_POSTE},
{k:"tf",q:"Une personne du même ménage peut retirer un acte de poursuite sans procuration.",v:false,ex:"Pour les actes de poursuite, une procuration est toujours requise. (Hors support.)",ref:HS_POSTE},
{k:"qcm",q:"Qu’est-ce qu’une procuration postale ?",a:["Une autorisation donnée à une autre personne de retirer des envois", "Une facture établie pour un envoi livré avec du retard", "Une assurance supplémentaire contre la perte d’un colis", "Un formulaire de réclamation en cas d’envoi endommagé"],ex:"Avec une procuration, vous autorisez une ou plusieurs personnes à retirer vos envois. (Hors support.)",ref:HS_POSTE},
{k:"match",q:"Associez chaque situation à sa règle.",p:[["Procuration unique","Pour un envoi précis"],["Procuration permanente","Pour plusieurs envois dans la durée"],["Remise en main propre","Aucune procuration possible"],["Même ménage","Sans procuration, sauf poursuites"]],ex:"Règles de la Poste suisse. (Hors support.)",ref:HS_POSTE},
{k:"qcm",q:"Quel type de procuration une entreprise cliente doit-elle utiliser à la Poste ?",a:["Une procuration permanente","Une procuration unique par téléphone","Aucune, le nom de l’entreprise suffit","Un simple e-mail du directeur"],ex:"Les clients commerciaux passent par une procuration permanente. (Hors support.)",ref:HS_POSTE},
{k:"multi",q:"Quelles pièces d’identité sont acceptées pour retirer un envoi avec procuration ?",good:["Passeport","Carte d’identité","Permis de conduire suisse","Livret pour étrangers"],bad:["Livret de famille","Photocopie de la carte d’identité"],ex:"Original d’une pièce avec photo ; le livret de famille n’est pas accepté. (Hors support.)",ref:HS_POSTE},
{k:"tf",q:"Une photocopie de la carte d’identité suffit pour retirer un recommandé avec procuration.",v:false,ex:"Il faut présenter l’original d’une pièce d’identité avec photo. (Hors support.)",ref:HS_POSTE},
{k:"fill",q:"Un envoi « Remise en main propre » doit être retiré par le destinataire ___.",a:["lui-même","par procuration","par un voisin","par sa famille"],ex:"Aucune procuration ne peut être établie pour la remise en main propre. (Hors support.)",ref:HS_POSTE},
{k:"sort",q:"Faut-il une procuration ? Classez.",c:["Sans procuration","Procuration nécessaire","Impossible, même avec procuration"],it:[["Conjoint du ménage, colis ordinaire",0],["Ami, lettre recommandée",1],["Collègue, envoi « Remise en main propre »",2],["Fils du ménage, acte de poursuite",1],["Voisin, colis Signature",1]],ex:"Ménage : libre sauf poursuites ; tiers : procuration ; main propre : destinataire seul. (Hors support.)",ref:HS_POSTE},
{k:"qcm",q:"Que confirme la signature de la personne qui reçoit un recommandé ?",a:["La remise de l’envoi","Le paiement des frais de port","L’ouverture de l’envoi","L’accord avec le contenu de la lettre"],ex:"Les mandataires confirment la réception par leur signature. (Hors support.)",ref:HS_POSTE},
{k:"odd",q:"Trouvez l’intrus : ces personnes peuvent recevoir pour vous un colis ordinaire au guichet, sauf une.",a:["Un passant qui propose de le prendre","Votre conjoint qui vit avec vous","Une personne avec votre procuration permanente","Une personne avec une procuration unique"],ex:"Sans lien de ménage ni procuration, personne n’est habilité. (Hors support.)",ref:HS_POSTE},
{k:"order",q:"Retrait d’un recommandé par un mandataire au guichet : remettez dans l’ordre.",a:["Présenter l’avis de retrait et la procuration","Montrer l’original d’une pièce d’identité avec photo","Contrôle de l’identité et de la procuration","Signature du mandataire","Remise de l’envoi"],ex:"L’identité est vérifiée, puis la signature prouve la remise. (Hors support.)",ref:HS_POSTE},
{k:"qcm",q:"Pourquoi vérifier l’identité pour un colis Signature ou un recommandé ?",a:["Pour prouver la remise à la bonne personne","Pour compléter les statistiques de la tournée","Pour encaisser des frais supplémentaires","Pour vérifier l’âge du client"],ex:"Le destinataire ou le mandataire doit justifier son identité. (Hors support.)",ref:HS_POSTE},
{k:"tf",q:"Une gérance avec service de loge peut, grâce à sa procuration, recevoir les actes judiciaires des locataires.",v:false,ex:"La procuration des prestataires de services exclut actes judiciaires, poursuites et envois en main propre. (Hors support.)",ref:HS_POSTE},
{k:"qcm",q:"Selon l’art. 321ter CP, quand une atteinte au secret postal n’est-elle pas punissable ?",a:["Si elle est requise pour déterminer l’ayant droit", "Si l’envoi concerné a une faible valeur marchande", "Si le destinataire est absent lors de la livraison", "Si le livreur est pressé en fin de tournée"],ex:"Al. 4 : pas punissable si nécessaire pour déterminer l’ayant droit ou prévenir un dommage. (Hors support.)",ref:"Hors support · CP 321ter al. 4"},
{k:"case",s:"Vous livrez un colis Signature. Le destinataire est absent ; son voisin propose de signer à sa place, sans procuration.",q:"Que faites-vous ?",a:["Vous laissez un avis de retrait au destinataire","Vous le remettez, le voisin le connaît bien","Vous signez vous-même à la place du client","Vous le déposez devant la porte"],ex:"Le voisin n’est pas habilité : l’envoi attend le destinataire ou son mandataire. (Hors support.)",ref:HS_POSTE},
{k:"case",s:"Une femme veut retirer au guichet une lettre recommandée adressée à son mari, avec qui elle vit. Ce n’est pas un acte de poursuite.",q:"Peut-elle la retirer ?",a:["Oui, le même ménage n’a pas besoin de procuration","Non, seul le mari peut retirer un recommandé","Oui, mais seulement avec une procuration permanente","Non, sauf si elle paie des frais"],ex:"Même ménage : pas de procuration, sauf pour les actes de poursuite. (Hors support.)",ref:HS_POSTE},
{k:"case",s:"Un homme veut retirer sans procuration un commandement de payer adressé à son frère, avec qui il habite.",q:"Quelle réponse est correcte ?",a:["Refuser : pour les poursuites, une procuration est requise", "Accepter, puisqu’ils vivent tous deux dans le même ménage", "Accepter s’il présente l’original de sa carte d’identité", "Accepter s’il promet de le transmettre le soir même"],ex:"Exception au ménage : les actes de poursuite exigent toujours une procuration. (Hors support.)",ref:HS_POSTE},
{k:"case",s:"Votre entreprise de logistique veut que le chef de quai retire chaque jour en filiale les envois adressés à l’entreprise.",q:"Quelle solution choisir ?",a:["Établir une procuration permanente à son nom","Lui donner une procuration unique par téléphone","Rien, l’uniforme de l’entreprise suffit","Lui confier la carte d’identité du directeur"],ex:"Pour un client commercial et des retraits réguliers : procuration permanente. (Hors support.)",ref:HS_POSTE},
{k:"case",s:"Pour retirer un colis avec procuration, un client présente une photo de sa carte d’identité sur son téléphone.",q:"Que faites-vous ?",a:["Demander l’original d’une pièce d’identité avec photo", "Accepter, car la photo sur le téléphone est bien nette", "Accepter, puisque la procuration est correctement signée", "Demander à la place son livret de famille original"],ex:"Seul l’original d’une pièce d’identité avec photo est accepté. (Hors support.)",ref:HS_POSTE},
{k:"case",s:"Un envoi porte la mention « Remise en main propre ». La destinataire envoie son assistant avec une procuration permanente.",q:"L’assistant peut-il retirer l’envoi ?",a:["Non, la remise en main propre exclut toute procuration", "Oui, la procuration permanente couvre tous les envois", "Oui, s’il présente sa propre carte d’identité originale", "Oui, à condition qu’il signe deux fois le justificatif"],ex:"Pour la remise en main propre, le destinataire doit venir lui-même. (Hors support.)",ref:HS_POSTE},
{k:"case",s:"Lors d’une livraison en entreprise, la réceptionniste de l’accueil propose de signer pour un colis adressé à l’entreprise.",q:"Est-ce acceptable ?",a:["Oui, si l’entreprise l’a habilitée à recevoir les marchandises", "Non, seul le directeur de l’entreprise a le droit de signer", "Non, une entreprise ne peut recevoir aucun colis Signature", "Oui, n’importe quel visiteur présent à l’accueil peut signer"],ex:"En entreprise, la marchandise se remet à une personne habilitée par l’entreprise.",ref:"Plan de formation · compétence d5"},
{k:"case",s:"Un livreur pressé dépose un colis Signature devant la porte et valide lui-même le terminal.",q:"Quel risque crée-t-il ?",a:["La remise n’est pas prouvée, le colis peut disparaître", "Aucun, le client gagne du temps et sera satisfait", "Le colis Signature devient alors un envoi ordinaire", "Seul le destinataire est responsable de son colis"],ex:"La signature prouve la remise à la bonne personne ; sans elle, le livreur et l’entreprise sont exposés.",ref:"Plan de formation · compétence d5"},
{k:"case",s:"À la livraison d’un recommandé, une personne affirme être la destinataire, mais le nom de sa pièce d’identité ne correspond pas.",q:"Que faites-vous ?",a:["Ne pas remettre l’envoi et laisser un avis de retrait", "Le remettre, puisqu’elle connaît le contenu de l’envoi", "Le remettre contre une signature et un pourboire", "Ouvrir l’envoi devant elle pour vérifier le contenu"],ex:"L’identité doit être justifiée : en cas de doute, pas de remise. (Hors support.)",ref:HS_POSTE},
{k:"case",s:"Un client veut que sa voisine retire un seul colis en filiale pendant ses vacances.",q:"Quelle procuration est la plus adaptée ?",a:["Une procuration unique pour cet envoi","Une procuration permanente payante","Aucune, la voisine peut le retirer librement","Une remise en main propre"],ex:"La procuration unique couvre un envoi précis ; elle est gratuite pour les particuliers. (Hors support.)",ref:HS_POSTE}
]}
];

